using System;using System.IO;using System.Reflection;using System.Diagnostics;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Forms;
sealed partial class WorldWindow {
 Process pdfConversionProcess;OfficeProcessJob pdfConversionJob;bool pdfConversionBusy,pdfConversionCancelled;
 string PDFEnginePath(){return Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"Tools","PDF","Jago-PDF-Engine.exe");}
 async Task HandlePDFExport(Dictionary<string,object> message){var json=new JavaScriptSerializer{MaxJsonLength=40000000};string type=Convert.ToString(message["type"]),request=message.ContainsKey("id")?Convert.ToString(message["id"]):"";if(type=="pdf-engine-status"){browser.CoreWebView2.PostWebMessageAsJson(json.Serialize(new{type="pdf-engine-status",available=File.Exists(PDFEnginePath())}));return;}if(type=="pdf-engine-cancel"){pdfConversionCancelled=true;if(pdfConversionJob!=null)pdfConversionJob.Dispose();try{if(pdfConversionProcess!=null&&!pdfConversionProcess.HasExited)pdfConversionProcess.Kill();}catch{}return;}if(pdfConversionBusy){browser.CoreWebView2.PostWebMessageAsJson(json.Serialize(new{type="pdf-engine-result",id=request,error="Another document is already converting."}));return;}pdfConversionBusy=true;pdfConversionCancelled=false;string work=Path.Combine(Program.Root,"PDF-conversion",Guid.NewGuid().ToString("N"));try{if(!File.Exists(PDFEnginePath()))throw new Exception("The offline PDF engine is missing. Keep the Tools folder beside Jago Library.exe.");string encoded=Convert.ToString(message["data"]);if(encoded.Length>28000000)throw new Exception("Convert a PDF under 20 MB at once.");byte[] bytes=Convert.FromBase64String(encoded);if(bytes.Length>20000000)throw new Exception("Convert a PDF under 20 MB at once.");Directory.CreateDirectory(work);string source=Path.Combine(work,"input.pdf"),destination=Path.Combine(work,"output.docx");File.WriteAllBytes(source,bytes);var start=new ProcessStartInfo(PDFEnginePath()){Arguments="\""+source+"\" \""+destination+"\" --layout "+(message.ContainsKey("layout")&&Convert.ToString(message["layout"])=="positioned"?"positioned":"flow"),UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=Path.GetDirectoryName(PDFEnginePath())};using(var process=new Process{StartInfo=start})using(var job=new OfficeProcessJob()){pdfConversionJob=job;pdfConversionProcess=process;process.Start();job.Attach(process);var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();var finished=Task.Run(()=>process.WaitForExit());if(await Task.WhenAny(finished,Task.Delay(120000))!=finished){job.Dispose();try{process.Kill();}catch{}throw new Exception("Conversion took too long. Try fewer pages or a built-in export mode.");}string output=await stdout,error=await stderr;if(pdfConversionCancelled)throw new Exception("Conversion cancelled. No file saved.");if(process.ExitCode!=0||!File.Exists(destination))throw new Exception("This PDF could not be reconstructed. Try Readable text or Preserve appearance. "+(error.Length>600?error.Substring(error.Length-600):error));if(new FileInfo(destination).Length>20000000)throw new Exception("The converted Word file exceeds 20 MB. Convert fewer pages.");string data=Convert.ToBase64String(File.ReadAllBytes(destination));browser.CoreWebView2.PostWebMessageAsJson(json.Serialize(new{type="pdf-engine-result",id=request,data=data,summary=output.Substring(Math.Max(0,output.Length-1500))}));}}catch(Exception error){browser.CoreWebView2.PostWebMessageAsJson(json.Serialize(new{type="pdf-engine-result",id=request,error=error.Message}));}finally{pdfConversionJob=null;pdfConversionProcess=null;pdfConversionBusy=false;try{if(Directory.Exists(work))Directory.Delete(work,true);}catch{}}}
}
